  def check_concrete_output(recovery_frame: Power_Propulsion_Availability_Supervisor.RecoveryFrame => B,
                            recovery_gate: Power_Propulsion_Availability_Supervisor.RecoveryGate.Type => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val recovery_frameValue: Power_Propulsion_Availability_Supervisor.RecoveryFrame = get_recovery_frame().get
    if(!recovery_frame(recovery_frameValue)) {
      testFailures = testFailures :+ st"'recovery_frame' did not match expected: value of the outgoing data port is ${recovery_frameValue}"
