    val recovery_gateValue: Power_Propulsion_Availability_Supervisor.RecoveryGate.Type = get_recovery_gate().get
    if(!recovery_gate(recovery_gateValue)) {
      testFailures = testFailures :+ st"'recovery_gate' did not match expected: value of the outgoing data port is ${recovery_gateValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


